import { test, expect, Page } from '@playwright/test';

test.describe('Network Timeout Retry Button', () => {
  let page: Page;

  test.beforeEach(async ({ browser }) => {
    page = await browser.newPage();
    await page.goto('http://localhost:3000');
  });

  test('should display retry button when network request times out', async () => {
    // Simulate a network timeout by aborting the request
    await page.route('**/api/data', route => {
      setTimeout(() => {
        route.abort('timedout');
      }, 100);
    });

    // Trigger the action that makes the network request
    await page.getByRole('button', { name: /fetch data/i }).click();

    // Wait for the timeout error message to appear
    await expect(page.getByText(/request timed out/i)).toBeVisible({ timeout: 5000 });

    // Verify the retry button is displayed
    const retryButton = page.getByRole('button', { name: /retry/i });
    await expect(retryButton).toBeVisible();
    await expect(retryButton).toBeEnabled();
  });

  test('should successfully retry the request after timeout', async () => {
    let requestCount = 0;

    // First request times out, subsequent requests succeed
    await page.route('**/api/data', route => {
      requestCount++;
      if (requestCount === 1) {
        setTimeout(() => {
          route.abort('timedout');
        }, 100);
      } else {
        route.continue();
      }
    });

    // Trigger the initial request
    await page.getByRole('button', { name: /fetch data/i }).click();

    // Wait for timeout error
    await expect(page.getByText(/request timed out/i)).toBeVisible({ timeout: 5000 });

    // Click the retry button
    await page.getByRole('button', { name: /retry/i }).click();

    // Verify the data is loaded successfully after retry
    await expect(page.getByText(/data loaded successfully/i)).toBeVisible({ timeout: 5000 });
    await expect(page.getByText(/request timed out/i)).not.toBeVisible();
  });

  test('should disable retry button while request is in progress', async () => {
    await page.route('**/api/data', route => {
      setTimeout(() => {
        route.continue();
      }, 2000);
    });

    // Trigger the request
    await page.getByRole('button', { name: /fetch data/i }).click();

    // Wait for loading state
    await expect(page.getByText(/loading/i)).toBeVisible();

    // Verify retry button is not visible during loading
    const retryButton = page.getByRole('button', { name: /retry/i });
    await expect(retryButton).not.toBeVisible();

    // Wait for request to complete
    await expect(page.getByText(/data loaded successfully/i)).toBeVisible({ timeout: 5000 });
  });

  test('should show error message with retry button on multiple timeout attempts', async () => {
    let requestCount = 0;

    await page.route('**/api/data', route => {
      requestCount++;
      if (requestCount <= 2) {
        setTimeout(() => {
          route.abort('timedout');
        }, 100);
      } else {
        route.continue();
      }
    });

    // First attempt
    await page.getByRole('button', { name: /fetch data/i }).click();
    await expect(page.getByText(/request timed out/i)).toBeVisible({ timeout: 5000 });

    // First retry
    await page.getByRole('button', { name: /retry/i }).click();
    await expect(page.getByText(/request timed out/i)).toBeVisible({ timeout: 5000 });

    // Second retry - should succeed
    await page.getByRole('button', { name: /retry/i }).click();
    await expect(page.getByText(/data loaded successfully/i)).toBeVisible({ timeout: 5000 });
  });

  test('should clear error message when user initiates new request', async () => {
    await page.route('**/api/data', route => {
      route.abort('timedout');
    });

    // Trigger request that times out
    await page.getByRole('button', { name: /fetch data/i }).click();
    await expect(page.getByText(/request timed out/i)).toBeVisible({ timeout: 5000 });

    // Change route to succeed
    await page.unroute('**/api/data');
    await page.route('**/api/data', route => {
      route.continue();
    });

    // Click retry button
    await page.getByRole('button', { name: /retry/i }).click();

    // Verify error message is cleared and data loads
    await expect(page.getByText(/request timed out/i)).not.toBeVisible();
    await expect(page.getByText(/data loaded successfully/i)).toBeVisible({ timeout: 5000 });
  });
});
